/**
 * Orbit Visual Memory — Sprint 6
 *
 * Stores captioned screenshots in the SQLite vector store so Orbit can
 * "remember what it saw" and answer questions about past screen states.
 *
 * Architecture:
 * - Separate SQLite table `visual_screenshots` (caption + embedding + base64 thumb)
 * - Caption generated by Gemini Flash multimodal (brief, factual)
 * - Embedding stored via the shared EmbeddingProvider
 * - Pruning: rows older than `retentionDays` are deleted on startup
 *
 * Public API:
 *   captureAndIndex(prompt?)    → captures screen + captions + indexes
 *   indexScreenshot(base64, opts) → index a pre-captured screenshot
 *   searchVisual(query, topK)   → semantic search over captions
 *   getRecentScreenshots(limit) → last N entries
 *   pruneOldEntries()           → delete entries past retentionDays
 */

import Database                         from "better-sqlite3";
import screenshot                       from "screenshot-desktop";
import os                               from "os";
import fs                               from "fs/promises";
import path                             from "path";
import crypto                           from "crypto";
import { fileURLToPath }                from "url";
import { GoogleGenAI }                  from "@google/genai";
import { createLogger }                 from "../infra/logger.js";
import { getEmbeddingProvider }         from "./embedding-provider.js";
import { getConfig }                    from "../config/config.js";

const log = createLogger("visual-memory");
const __dirname = path.dirname(fileURLToPath(import.meta.url));
const DB_PATH = path.join(__dirname, "../../data/memory.db");

// ── Types ────────────────────────────────────────────────────────────────────

export interface VisualEntry {
    id:        number;
    sessionId: string;
    timestamp: number;   // Unix ms
    caption:   string;
    thumbB64:  string;   // small JPEG thumbnail (base64) — optional, may be ""
    score?:    number;   // search relevance (0-1)
}

export interface IndexScreenshotOptions {
    sessionId?:      string;
    captionPrompt?:  string;   // override default caption prompt
    storeThumbnail?: boolean;  // whether to persist the full base64 (default: false)
}

// ── DB helpers ───────────────────────────────────────────────────────────────

function openDb(): Database.Database {
    const db = new Database(DB_PATH);
    db.pragma("journal_mode = WAL");
    db.exec(`
        CREATE TABLE IF NOT EXISTS visual_screenshots (
            id          INTEGER PRIMARY KEY AUTOINCREMENT,
            session_id  TEXT    NOT NULL DEFAULT '',
            timestamp   INTEGER NOT NULL,
            caption     TEXT    NOT NULL,
            thumb_b64   TEXT    NOT NULL DEFAULT '',
            embedding   TEXT    NOT NULL DEFAULT '[]'
        );
        CREATE INDEX IF NOT EXISTS idx_vs_timestamp ON visual_screenshots(timestamp DESC);
    `);
    return db;
}

// ── Caption generation ───────────────────────────────────────────────────────

async function generateCaption(base64img: string, prompt: string, model: string): Promise<string> {
    const apiKey = process.env.GEMINI_API_KEY;
    if (!apiKey) throw new Error("GEMINI_API_KEY no configurada");

    const ai = new GoogleGenAI({ apiKey });
    const response = await ai.models.generateContent({
        model,
        contents: [{
            role: "user",
            parts: [
                { inlineData: { mimeType: "image/png", data: base64img } },
                { text: prompt },
            ],
        }],
    });
    return (response.text || "").trim().slice(0, 2000);
}

// ── Vector similarity ────────────────────────────────────────────────────────

function cosineSimilarity(a: number[], b: number[]): number {
    if (a.length !== b.length || a.length === 0) return 0;
    let dot = 0, na = 0, nb = 0;
    for (let i = 0; i < a.length; i++) {
        dot += a[i] * b[i];
        na  += a[i] * a[i];
        nb  += b[i] * b[i];
    }
    const denom = Math.sqrt(na) * Math.sqrt(nb);
    return denom === 0 ? 0 : dot / denom;
}

// ── Public API ───────────────────────────────────────────────────────────────

/**
 * Capture the current screen, generate a caption, and index it.
 */
export async function captureAndIndex(opts: IndexScreenshotOptions = {}): Promise<VisualEntry | null> {
    const cfg = getConfig();
    if (!cfg.memory.visual.enabled) {
        log.debug("Visual memory desactivada (memory.visual.enabled = false)");
        return null;
    }

    const tempPath = path.join(os.tmpdir(), `orbit_vis_${Date.now()}.png`);
    try {
        await (screenshot as any)({ filename: tempPath });
        const buf     = await fs.readFile(tempPath);
        const b64     = buf.toString("base64");
        const result  = await indexScreenshot(b64, opts);
        return result;
    } catch (err: any) {
        log.warn("captureAndIndex falló:", err.message);
        return null;
    } finally {
        try { await fs.unlink(tempPath); } catch { /* ignore */ }
    }
}

/**
 * Index a pre-captured screenshot (base64 PNG/JPEG).
 */
export async function indexScreenshot(
    base64img: string,
    opts: IndexScreenshotOptions = {},
): Promise<VisualEntry | null> {
    const cfg = getConfig();
    const model = cfg.memory.visual.captionModel;

    const captionPrompt = opts.captionPrompt
        ?? "Describe concisamente (máx 3 frases) qué se ve en esta pantalla: app activa, contenido principal, acciones en curso.";

    let caption = "";
    try {
        caption = await generateCaption(base64img, captionPrompt, model);
        log.debug(`Caption generada (${caption.length} chars)`);
    } catch (err: any) {
        log.warn("No se pudo generar caption:", err.message);
        caption = `[screenshot ${new Date().toISOString()}]`;
    }

    // Generate embedding for semantic search
    let embeddingArr: number[] = [];
    try {
        const provider = getEmbeddingProvider();
        if (provider) {
            const vecs = await provider.embed([caption]);
            embeddingArr = vecs[0] ?? [];
        }
    } catch (err: any) {
        log.debug("Sin embedding:", err.message);
    }

    const thumbB64 = opts.storeThumbnail ? base64img : "";
    const now      = Date.now();

    const db = openDb();
    try {
        const stmt = db.prepare(`
            INSERT INTO visual_screenshots (session_id, timestamp, caption, thumb_b64, embedding)
            VALUES (?, ?, ?, ?, ?)
        `);
        const info = stmt.run(
            opts.sessionId || "default",
            now,
            caption,
            thumbB64,
            JSON.stringify(embeddingArr),
        );

        const entry: VisualEntry = {
            id:        info.lastInsertRowid as number,
            sessionId: opts.sessionId || "default",
            timestamp: now,
            caption,
            thumbB64,
        };
        log.info(`Screenshot indexado [id=${entry.id}]`);
        return entry;
    } finally {
        db.close();
    }
}

/**
 * Search visual memory by natural-language query.
 * Uses vector similarity if embedding provider available, otherwise keyword match on captions.
 */
export async function searchVisual(query: string, topK = 5): Promise<VisualEntry[]> {
    const db = openDb();
    try {
        // Get all entries (dataset typically small — visual memory is bounded by retention)
        const rows = db.prepare(
            "SELECT id, session_id, timestamp, caption, thumb_b64, embedding FROM visual_screenshots ORDER BY timestamp DESC LIMIT 500"
        ).all() as Array<{
            id: number; session_id: string; timestamp: number;
            caption: string; thumb_b64: string; embedding: string;
        }>;

        if (rows.length === 0) return [];

        // Attempt vector search
        let queryEmbedding: number[] = [];
        try {
            const provider = getEmbeddingProvider();
            if (provider) {
                const vecs = await provider.embed([query]);
                queryEmbedding = vecs[0] ?? [];
            }
        } catch { /* fallback to keyword */ }

        let scored: Array<VisualEntry & { score: number }>;

        if (queryEmbedding.length > 0) {
            scored = rows.map(r => {
                const emb = JSON.parse(r.embedding || "[]") as number[];
                const sim = cosineSimilarity(queryEmbedding, emb);
                return { id: r.id, sessionId: r.session_id, timestamp: r.timestamp, caption: r.caption, thumbB64: r.thumb_b64, score: sim };
            });
        } else {
            // Keyword fallback
            const lq = query.toLowerCase();
            scored = rows.map(r => {
                const lc = r.caption.toLowerCase();
                const score = lc.includes(lq) ? 0.7 : [...lq.split(" ")].filter(w => w.length > 2 && lc.includes(w)).length / lq.split(" ").length;
                return { id: r.id, sessionId: r.session_id, timestamp: r.timestamp, caption: r.caption, thumbB64: r.thumb_b64, score };
            });
        }

        return scored
            .sort((a, b) => b.score - a.score)
            .slice(0, topK)
            .filter(e => e.score > 0.05);
    } finally {
        db.close();
    }
}

/**
 * Return the N most recent visual memory entries.
 */
export function getRecentScreenshots(limit = 10): VisualEntry[] {
    const db = openDb();
    try {
        const rows = db.prepare(
            "SELECT id, session_id, timestamp, caption, thumb_b64 FROM visual_screenshots ORDER BY timestamp DESC LIMIT ?"
        ).all(limit) as Array<{ id: number; session_id: string; timestamp: number; caption: string; thumb_b64: string }>;
        return rows.map(r => ({
            id:        r.id,
            sessionId: r.session_id,
            timestamp: r.timestamp,
            caption:   r.caption,
            thumbB64:  r.thumb_b64,
        }));
    } finally {
        db.close();
    }
}

/**
 * Delete entries older than memory.visual.retentionDays.
 */
export function pruneOldEntries(): number {
    const cfg  = getConfig();
    const days = cfg.memory.visual.retentionDays;
    const cutoff = Date.now() - days * 24 * 60 * 60 * 1000;
    const db = openDb();
    try {
        const result = db.prepare("DELETE FROM visual_screenshots WHERE timestamp < ?").run(cutoff);
        const deleted = result.changes;
        if (deleted > 0) log.info(`Visual memory: eliminadas ${deleted} entradas antiguas (>${days}d)`);
        return deleted;
    } finally {
        db.close();
    }
}

/**
 * Return total count of visual memory entries.
 */
export function visualMemoryStats(): { total: number; oldest: number | null; newest: number | null } {
    const db = openDb();
    try {
        const row = db.prepare(
            "SELECT COUNT(*) as total, MIN(timestamp) as oldest, MAX(timestamp) as newest FROM visual_screenshots"
        ).get() as { total: number; oldest: number | null; newest: number | null };
        return row;
    } finally {
        db.close();
    }
}
